const details={sim:['电商平台的佣金与补贴策略研究','2026.01—2026.05 · 毕业论文。将电商竞争问题抽象为多智能体仿真模型，构建四类主体。设计单平台静态、双平台静态竞争和双平台动态博弈三组实验，比较 16 种策略组合下各方决策路径与结果，并用帕累托前沿识别规模增长、收益回收与生态稳定之间的均衡点。'],rec:['图书推荐系统','2025.05—2025.06 · CCF 大数据与计算智能大赛训练赛，排名 2/333。基于 600 万条用户与图书交互数据，研究并实现 NCF、DeepFM、DCN 等推荐模型。采用 BERT4Rec 捕捉用户动态兴趣，结合数据增强缓解稀疏性，构建混合推荐模型。'],gai:['科技平权：GAI 创新驱动下的社会公平与发展','2024.12—2025.07 · 计算机设计大赛国家二等奖。通过爬虫等渠道获取数据，运用 NLP 情感分析、主成分分析、面板回归与空间效应分析，评估生成式人工智能普惠发展的机遇与风险。参与研究报告全文撰写、制作答辩材料，并主导导师沟通与三次答辩。'],flow:['平台券自动分析 AI Skill','在 TikTok Shop 实习期间，针对每月人工拆券耗时的问题，独立设计自动分析平台券的 AI Skill，并接入飞书，实现数据自动读取、标准化提取、环比比较和分析结果回写，帮助定位平台或月份之间的发券策略变化。']};
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.project').forEach(p=>p.hidden=b.dataset.filter!=='all'&&p.dataset.category!==b.dataset.filter)}));
const dialog=document.getElementById('detail');document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{const d=details[b.dataset.detail];document.getElementById('detail-title').textContent=d[0];document.getElementById('detail-body').textContent=d[1];dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
